// Keep each browser tab's Supabase traffic small and retry temporary DB connection exhaustion.
let activeDbRequests=0;const dbRequestQueue=[];async function limitedDbFetch(input,init){
 await new Promise(resolve=>{if(activeDbRequests<2){activeDbRequests++;resolve()}else dbRequestQueue.push(resolve)});
 try{
  for(let attempt=0;attempt<3;attempt++){
   const response=await fetch(input,init);
   if(response.ok||attempt===2)return response;
   let message='';try{message=await response.clone().text()}catch{}
   if(!/too many connections issued to the database|too many connections/i.test(message))return response;
   await new Promise(r=>setTimeout(r,700*(attempt+1)));
  }
 }finally{activeDbRequests--;const next=dbRequestQueue.shift();if(next)next()}
}
