async function loadProductReviews(productId){const host=$('#reviewsList');if(!host)return;const {data,error}=await db.from('product_reviews').select('id,customer_name,rating,review_text,created_at').eq('product_id',productId).eq('approved',true).order('created_at',{ascending:false}).limit(30);if(error){host.innerHTML='<p class="muted">রিভিউ এখন লোড করা যাচ্ছে না। পরে আবার চেষ্টা করুন।</p>';return}const rows=data||[],avg=rows.length?rows.reduce((a,r)=>a+Number(r.rating),0)/rows.length:0;$('#productRatingSummary').innerHTML=rows.length?`<span class="stars">${'★'.repeat(Math.round(avg))}${'☆'.repeat(5-Math.round(avg))}</span> ${avg.toFixed(1)} / 5 · ${rows.length}টি রিভিউ`:'এখনো কোনো রিভিউ নেই';$('#reviewCountLabel').textContent=rows.length+' reviews';host.innerHTML=rows.map(r=>`<article class="review-card"><div class="review-card-top"><b>${esc(r.customer_name)}</b><span class="stars">${'★'.repeat(Number(r.rating))}${'☆'.repeat(5-Number(r.rating))}</span></div><p>${esc(r.review_text)}</p><small>${new Date(r.created_at).toLocaleDateString('bn-BD',{year:'numeric',month:'short',day:'numeric'})}</small></article>`).join('')||'<p class="muted">এই পণ্যের প্রথম রিভিউটি আপনিই দিতে পারেন।</p>'}
function productUrl(id){const u=new URL(window.location.href);u.search='';u.hash='';u.searchParams.set('product',String(id));return u.toString()}
async function copyProductLink(id){if(location.protocol==='file:'){toast('আপনি এখন HTML ফাইলটি কম্পিউটার থেকে চালাচ্ছেন। এই অবস্থায় শেয়ারযোগ্য লিংক তৈরি হবে না। আগে ওয়েবসাইটটি Netlify/অন্য হোস্টিংয়ে Publish করুন; তারপর অনলাইন ওয়েবসাইট থেকে এই বাটনে ক্লিক করে লিংক কপি করুন।');return}const url=productUrl(id);try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(url)}else{const input=document.createElement('textarea');input.value=url;input.style.position='fixed';input.style.opacity='0';document.body.appendChild(input);input.select();const ok=document.execCommand('copy');input.remove();if(!ok)throw Error('copy failed')}toast('এই পণ্যের পাবলিক লিংক কপি হয়েছে। এখন WhatsApp/Facebook-এ শেয়ার করতে পারবেন।')}catch(err){prompt('পণ্যের লিংক কপি করুন:',url)}}
