function renderSlides(){
 const active=slides.filter(s=>s.active!==false&&s.image_url); clearInterval(slideTimer); const hero=$('#heroSlider');
 hero.querySelectorAll('.slide,.slide-fallback,.slider-dots,.slide-track').forEach(x=>x.remove());
 if(!active.length){const blank=document.createElement('div');blank.className='slide-fallback';blank.setAttribute('aria-label','Upload a banner from the admin panel');hero.prepend(blank);$('#slidePrev').hidden=true;$('#slideNext').hidden=true;return;}
 slideIndex=Math.min(Math.max(slideIndex,0),active.length-1);
 const track=document.createElement('div');track.className='slide-track';
 active.forEach((item,i)=>{const slide=document.createElement('div');slide.className='slide';const img=document.createElement('img');img.className='banner-image';img.src=item.image_url;img.alt='MH Fashion banner';img.loading=i===0?'eager':'lazy';img.decoding='async';img.onload=()=>{if(i===slideIndex){hero.style.aspectRatio=img.naturalWidth+'/'+img.naturalHeight;slide.classList.add('loaded');}};slide.appendChild(img);track.appendChild(slide);});
 hero.prepend(track);
 const move=()=>{track.style.transform='translate3d('+(-slideIndex*100)+'%,0,0)';const img=track.children[slideIndex]?.querySelector('img');if(img?.naturalWidth)hero.style.aspectRatio=img.naturalWidth+'/'+img.naturalHeight;}; move();
 if(active.length>1){const dots=document.createElement('div');dots.className='slider-dots';dots.innerHTML=active.map((_,i)=>'<button class="'+(i===slideIndex?'active':'')+'" data-dot="'+i+'" aria-label="Banner '+(i+1)+'"></button>').join('');hero.appendChild(dots);slideTimer=setInterval(()=>{slideIndex=(slideIndex+1)%active.length;move();dots.querySelectorAll('[data-dot]').forEach((b,i)=>b.classList.toggle('active',i===slideIndex));},5000);}
 $('#slidePrev').hidden=active.length<2;$('#slideNext').hidden=active.length<2;
}
function updateSiteSchema(){const name=settings.store_name||'MH Fashion',logo=settings.logo_url||'',sameAs=['facebook','instagram','tiktok','telegram'].map(k=>settings[k]).filter(Boolean),url='https://mhfashion.cc.cd/';const publisher={"@type":"Organization","name":name,"url":url};if(logo)publisher.logo={"@type":"ImageObject","url":logo};if(sameAs.length)publisher.sameAs=sameAs;const schema={"@context":"https://schema.org","@type":"WebSite","name":name,"alternateName":[name.replace(/\s+/g,''),name+' BD'],"url":url,"publisher":publisher};let el=$('#siteSchema');if(el)el.textContent=JSON.stringify(schema);let org=$('#organizationSchema');if(org)org.textContent=JSON.stringify({"@context":"https://schema.org","@type":"Organization","name":name,"url":url,...(logo?{logo}:{}),...(sameAs.length?{sameAs}: {})});let og=document.querySelector('meta[property="og:image"]');if(!og&&logo){og=document.createElement('meta');og.setAttribute('property','og:image');document.head.appendChild(og)}if(og&&logo)og.setAttribute('content',logo);let seo=$('#footerSeoCopy');if(seo)seo.textContent=name+' is an online fashion store in Bangladesh, offering selected fashion collections and Cash on Delivery.'}
function renderStoreIdentity(){const name=settings.store_name||'MH Fashion',tag=settings.tagline||'STYLE THAT SPEAKS',logo=settings.logo_url||'';document.title=name+' | Online Fashion Store';document.querySelector('meta[name="description"]')?.setAttribute('content',name+' — online fashion store in Bangladesh. Discover premium fashion, new arrivals and Cash on Delivery.');document.querySelector('meta[property="og:title"]')?.setAttribute('content',name+' | Online Fashion Store');document.querySelector('meta[property="og:site_name"]')?.setAttribute('content',name);$$('.brand-name').forEach(x=>x.textContent=name.toUpperCase());$$('.brand-tagline').forEach(x=>x.textContent=tag);$$('.brand:not(.footer-brand)').forEach(b=>{let mark=b.querySelector('.brand-mark');b.classList.toggle('has-custom-logo',!!logo);if(mark){mark.innerHTML=logo?`<img src="${esc(logo)}" alt="${esc(name)} logo" width="48" height="48" loading="eager" fetchpriority="high" decoding="async" onerror="this.onerror=null;this.style.display='none';this.parentElement.classList.add('logo-load-failed')">`:''}});$('#footerBrand').textContent=name.toUpperCase();$('#footerCopyright').textContent=settings.copyright||('© '+name+'. All rights reserved.');let contact=[];if(settings.phone)contact.push(`<a href="tel:${esc(settings.phone)}">Phone: ${esc(settings.phone)}</a>`);if(settings.contact_email)contact.push(`<a href="mailto:${esc(settings.contact_email)}">Email: ${esc(settings.contact_email)}</a>`);$('#contactInfo').innerHTML=contact.join('')||'Add your contact details from the admin panel.';let links=[['whatsapp','WhatsApp'],['telegram','Telegram'],['facebook','Facebook'],['instagram','Instagram'],['tiktok','TikTok']].filter(([k])=>settings[k]).map(([k,label])=>`<a class="social-link" href="${esc(settings[k])}" target="_blank" rel="noopener noreferrer"><span>${label}</span></a>`);$('#socialLinks').innerHTML=links.join('');updateSiteSchema()}
