let publicLoadPromise=null;
async function loadPublic(){
 if(publicLoadPromise)return publicLoadPromise;
 publicLoadPromise=(async()=>{
  const hadCache=restorePublicCache();
  if(!hadCache){renderProducts();renderSlides();renderStoreIdentity()}
  if(!ready)return;
  // Fetch public data concurrently; the custom fetch limiter still caps active Supabase requests.
  const refresh=async(table,apply)=>{
   try{const {data,error}=await db.from(table).select('*');if(error)throw error;apply(data||[]);savePublicCache()}
   catch(err){console.warn(table+' load failed:',err)}
  };
  await Promise.all([
   refresh('categories',data=>{categories=data.filter(c=>c.active!==false).sort((a,b)=>(a.sort_order||0)-(b.sort_order||0));renderProducts();populateProductCategories()}),
   refresh('products',data=>{products=data.filter(p=>p.active!==false).sort((a,b)=>new Date(b.created_at||0)-new Date(a.created_at||0));renderProducts();openProductFromUrl()}),
   refresh('hero_slides',data=>{slides=data.filter(s=>s.active!==false).sort((a,b)=>(a.sort_order||0)-(b.sort_order||0));renderSlides()}),
   refresh('store_settings',data=>{settings={delivery:0,store_name:'MH Fashion',tagline:'STYLE THAT SPEAKS',copyright:'© MH Fashion. All rights reserved.'};data.forEach(x=>settings[x.key]=x.value);renderStoreIdentity();populateSettingsForm()})
  ]);
 })();
 try{return await publicLoadPromise}finally{publicLoadPromise=null}
}
