async function uploadFile(file,bucket){
 if(!file)return null;
 if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>12*1024*1024)throw Error('JPG, PNG বা WebP ছবি দিন (সর্বোচ্চ ১২ MB)।');
 let upload=file,contentType=file.type,ext=file.type.split('/')[1].replace('jpeg','jpg');
 try{const bitmap=await createImageBitmap(file);if(!bitmap.width||!bitmap.height)throw Error('লোগো ছবিটি পড়া যাচ্ছে না। অন্য PNG/JPG/WebP ফাইল দিন।');const scale=Math.min(1,1200/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d',{alpha:true});ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',0.78));if(blob){upload=blob;contentType='image/webp';ext='webp'}}catch(e){console.warn('Image compression skipped:',e)}
 const path=crypto.randomUUID()+'.'+ext;const {error}=await db.storage.from(bucket).upload(path,upload,{contentType,upsert:false});if(error)throw error;return db.storage.from(bucket).getPublicUrl(path).data.publicUrl
}
