const orderStatusMap={'নতুন':{label:'Pending',cls:'pending',idx:0},'কনফার্ম':{label:'Confirmed',cls:'confirmed',idx:1},'নিশ্চিত হয়েছে':{label:'Confirmed',cls:'confirmed',idx:1},'প্রসেসিং':{label:'Processing',cls:'processing',idx:2},'প্রক্রিয়াধীন':{label:'Processing',cls:'processing',idx:2},'পাঠানো হয়েছে':{label:'Shipped',cls:'shipped',idx:3},'সম্পন্ন':{label:'Delivered',cls:'delivered',idx:4},'বাতিল':{label:'Cancelled',cls:'cancelled',idx:-1}};
function orderCard(o){const st=orderStatusMap[o.status]||{label:o.status||'Pending',cls:'pending',idx:0};const items=Array.isArray(o.items)?o.items.map(x=>`${esc(x.name||'Product')} × ${Number(x.qty||0)}${x.size?` · ${esc(x.size)}`:''}${x.length?` · ${esc(x.length)}`:''}`).join('<br>'):'Order items';const labels=['Pending','Confirmed','Processing','Shipped','Delivered'];let progress='';if(st.idx>=0)progress=`<div class=\"order-progress\">${labels.map((_,i)=>`<span class=\"order-step ${i<st.idx?'done':i===st.idx?'current':''}\"></span>`).join('')}</div><div class=\"order-progress-labels\">${labels.map(x=>`<span>${x}</span>`).join('')}</div>`;let expected='';if(st.idx<4&&st.idx>=0){const d=new Date(o.created_at);d.setDate(d.getDate()+4);expected=`<div class=\"order-arrival\"><strong>Estimated delivery:</strong> ${d.toLocaleDateString('en-BD',{day:'numeric',month:'long',year:'numeric'})}</div>`}else if(st.idx===4){expected=`<div class=\"order-arrival\"><strong>Delivered:</strong> Order completed successfully.</div>`}else if(st.idx<0){expected=`<div class=\"order-arrival\"><strong>Order cancelled.</strong> This order is no longer being processed.</div>`}return `<article class=\"order-card\"><div class=\"order-card-head\"><div><div class=\"order-id\">ORDER #${esc(String(o.id).slice(0,8).toUpperCase())}</div><h3>${esc(o.customer_name||'Customer')}</h3></div><div><span class=\"order-status ${st.cls}\">${st.label}</span><div class=\"order-total\">${money(o.total)}</div></div></div>${progress}<div class=\"order-meta\"><div>📅 ${new Date(o.created_at).toLocaleString('en-BD')}</div><div>📍 ${esc(o.district||'')} · ${esc(o.thana||o.area||'')} · ${esc(o.village||'')}</div></div>${expected}<div class=\"order-items\">${items}</div>${st.idx>=0&&st.idx<3?`<div class=\"order-actions\"><button class=\"cancel-order-btn\" data-cancel-order=\"${esc(o.id)}\">Cancel Order</button></div>`:''}<div class=\"order-note\">Status updates are shown here after the store confirms and processes your order.</div></article>`}
async function loadCustomerOrders(phone){const box=$('#ordersResult');const clean=phone.trim();box.innerHTML='<div class="order-empty">অর্ডার খোঁজা হচ্ছে...</div>';if(!/^([+]?\d[\d\s-]{9,16})$/.test(clean)){box.innerHTML='<div class="order-empty">সঠিক ফোন নম্বর দিন।</div>';return}let {data,error}=await db.rpc('get_customer_orders',{customer_phone:clean});if(error){box.innerHTML=`<div class="order-empty"><strong>অর্ডার লোড করা যাচ্ছে না।</strong><br><small>${esc(error.message)}</small><br><small>Supabase SQL Editor-এ সর্বশেষ supabase_setup.sql একবার Run করুন।</small></div>`;return}if(!data?.length){box.innerHTML='<div class="order-empty">এই ফোন নম্বর দিয়ে কোনো অর্ডার পাওয়া যায়নি। Checkout-এর সময় যে নম্বরটি দিয়েছিলেন, ঠিক সেই নম্বরটি দিন।</div>';return}box.innerHTML=data.map(orderCard).join('')}
