document.addEventListener('click',async e=>{let edit=e.target.closest('[data-product-edit]');if(edit){let {data}=await db.from('products').select('*').eq('id',edit.dataset.productEdit).single();if(data){populateProductCategories(data.category);let f=$('#productForm');let currentImages=productImages(data);f.dataset.existingImages=JSON.stringify(currentImages);$('#existingProductImages').innerHTML=currentImages.map((u,i)=>`<div class="image-preview-item"><img src="${esc(u)}" alt="বর্তমান ছবি ${i+1}"><small>ছবি ${i+1}</small></div>`).join('');Object.entries({id:data.id,name:data.name,price:data.price,old_price:data.old_price||'',category:data.category,stock:data.stock,description:data.description||'',active:data.active,featured:!!data.featured,flash_sale:!!data.flash_sale,flash_sale_price:data.flash_sale_price||'',flash_sale_end:data.flash_sale_end?String(data.flash_sale_end).slice(0,16):'',size_type:data.size_type||'none',size_options_text:(data.size_options||[]).join(', '),length_options_text:(data.length_options||[]).join(', '),size_note:data.size_note||''}).forEach(([k,v])=>{if(k==='active')f.elements[k].checked=v;else f.elements[k].value=v});$('#productFormTitle').textContent='পণ্য সম্পাদনা করুন';syncSizeFields();f.scrollIntoView({behavior:'smooth'})}}let del=e.target.closest('[data-product-delete]');if(del&&confirm('এই পণ্যটি মুছবেন?')){let {error}=await db.from('products').delete().eq('id',del.dataset.productDelete);if(error)toast(error.message);else{loadAdminProducts();loadPublic()}}let se=e.target.closest('[data-slide-edit]');if(se){let {data}=await db.from('hero_slides').select('*').eq('id',se.dataset.slideEdit).single();if(data){let f=$('#slideForm');f.elements.id.value=data.id;f.elements.active.checked=data.active;f.scrollIntoView({behavior:'smooth'})}}let sd=e.target.closest('[data-slide-delete]');if(sd&&confirm('এই স্লাইডটি মুছবেন?')){let {error}=await db.from('hero_slides').delete().eq('id',sd.dataset.slideDelete);if(error)toast(error.message);else{loadAdminSlides();loadPublic()}}});
function orderDetailsHtml(o){const items=Array.isArray(o.items)?o.items.map(i=>`<div class="detail-item-row"><div><b>${esc(i.name||'Product')}</b><small>Qty: ${digits(i.qty||0)}${i.size?' · Size: '+esc(i.size):''}${i.length?' · Length: '+esc(i.length)+' inches':''}</small></div><strong>${money(Number(i.price||0)*Number(i.qty||0))}</strong></div>`).join(''):'<p class="muted">No items</p>';const full=[`Order ID: ${o.id}`,`Customer Name: ${o.customer_name||''}`,`Phone: ${o.phone||''}`,`District: ${o.district||''}`,`Thana/Upazila: ${o.thana||o.area||''}`,`Village/Area: ${o.village||''}`,`Postcode: ${o.postcode||''}`,`Full Address: ${o.address||''}`,`Order Note: ${o.note||''}`,`Payment: ${o.payment_method||'Cash on Delivery'}`,`Status: ${o.status||''}`,`Order Date: ${new Date(o.created_at).toLocaleString('en-BD')}`,`Subtotal: ${money(o.subtotal)}`,`Delivery: ${money(o.delivery)}`,`Total: ${money(o.total)}`,`Items: ${(o.items||[]).map(i=>`${i.name} x ${i.qty}${i.size?' | Size '+i.size:''}${i.length?' | Length '+i.length+' inches':''}`).join('; ')}`].join('\n');return `<div class="order-detail-toolbar"><button class="primary-btn" type="button" id="copyWholeOrder">Copy All Order Details</button></div><div class="detail-grid"><div><span>Customer</span><b>${esc(o.customer_name||'')}</b></div><div><span>Phone</span><b>${esc(o.phone||'')}</b></div><div><span>District</span><b>${esc(o.district||'')}</b></div><div><span>Thana / Upazila</span><b>${esc(o.thana||o.area||'')}</b></div><div><span>Village / Area</span><b>${esc(o.village||'')}</b></div><div><span>Postcode</span><b>${esc(o.postcode||'—')}</b></div><div class="wide"><span>Full Address</span><b>${esc(o.address||'')}</b></div><div><span>Payment</span><b>${esc(o.payment_method||'Cash on Delivery')}</b></div><div><span>Status</span><b>${esc(o.status||'')}</b></div><div><span>Order Date</span><b>${esc(new Date(o.created_at).toLocaleString('en-BD'))}</b></div><div><span>Subtotal</span><b>${money(o.subtotal)}</b></div><div><span>Delivery</span><b>${money(o.delivery)}</b></div><div><span>Total</span><b>${money(o.total)}</b></div><div class="wide"><span>Customer Note</span><b>${esc(o.note||'—')}</b></div></div><section class="detail-items"><h3>Products</h3>${items}</section><textarea id="orderCopyText" class="order-copy-text" readonly>${esc(full)}</textarea>`}
document.addEventListener('click',async e=>{const view=e.target.closest('[data-admin-order]');if(view){const o=orders.find(x=>String(x.id)===String(view.dataset.adminOrder));if(!o)return;$('#adminOrderDetails').innerHTML=orderDetailsHtml(o);$('#adminOrderDetailsDialog').showModal();$('#copyWholeOrder').onclick=async()=>{const t=$('#orderCopyText')?.value||'';try{await navigator.clipboard.writeText(t);toast('অর্ডারের সম্পূর্ণ তথ্য কপি হয়েছে।')}catch(err){$('#orderCopyText').select();document.execCommand('copy');toast('অর্ডারের তথ্য কপি হয়েছে।')}}}});
document.addEventListener('change',async e=>{let s=e.target.closest('[data-order-status]');if(s){let {error}=await db.from('orders').update({status:s.value}).eq('id',s.dataset.orderStatus);if(error)toast(error.message)}});
(async()=>{renderCart();await loadPublic();if(ready){let {data}=await db.auth.getSession();if(data.session?.user&&await checkAdmin()){$('#loginForm').hidden=true;$('#adminArea').hidden=false;$('#adminStatus').textContent='লগইন: '+data.session.user.email;await loadCategories();await loadAdminProducts()}}})();
